+    BOOST_CHECK_EQUAL(c.GetRinHashEffectiveAt(599).min_peer_protocol_version, 0);
+    BOOST_CHECK_EQUAL(c.GetRinHashEffectiveAt(600).min_peer_protocol_version, 70018);
+}
+
+BOOST_AUTO_TEST_SUITE_END()

